Method.Implementation:

do ##super()
$$$TRACE(" $$$$$$$$$$$$$$$ Inside OnInit() method...")
#DIM status AS %Status
set status = $$$OK		
Do ..JavaGateway.%Import(..JarFile) 

try{
	set ..objCdrTuxService = ##class(org.ihc.itf.cdr.CdrHl7AddUpdate).%New(..JavaGateway,..ApplicationAddress, ..TuxedoService)		
}catch err{
   $$$TRACE("Exception while Creating Tuxedo Service: " _err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)	    	 
   set status=$$$ERROR(" Exception while initializing Tuxedo Service: "_err.AsSystemError()_"::"_err.Data_"::"_err.Code)

}	
Quit status

$$$TRACE(" $$$$$$$$$$$$$$$ Inside OnTearDown() method...")

Set tSC = $$$OK

Try {		
	If $IsObject(..objCdrTuxService) {
		$$$TRACE("Disconnecting from CDR Tuxedo service...")
		Do ..objCdrTuxService.shutdownTuxService()			
		Set ..objCdrTuxService = $$$NULLOREF
	}
}
Catch {
	Set tSC = $$$EnsSystemError
}
Set tSC = ##super()
Quit tSC

 #DIM status AS %Status
 set status = $$$OK	 
 try{

	 		$$$TRACE(" Calling MMIAdd .."_pRequest.hl7Msg.RawContent) 				 		
	 		set mshData = pRequest.hl7Msg.GetValueAt("MSH","",status)			 		
            set evnData = pRequest.hl7Msg.GetValueAt("EVN","",status)	
            set pidData = pRequest.hl7Msg.GetValueAt("PID","",status)	
	 		set hl7Data = mshData_$CHAR(13)_evnData_$CHAR(13)_pidData_$CHAR(13)		 		
	 		$$$TRACE("Hl7 Data: "_hl7Data)
	 		set pResponse=##class(Ens.StringResponse).%New()
	 		$$$TRACE("$IsObject : "_$IsObject(..objCdrTuxService))		 		
	 		Set pResponse.StringValue = ..objCdrTuxService.callAddUpdate(hl7Data)
	 		Set respData = pResponse.StringValue		 		
	 		$$$TRACE(" Call after the MMIAddUpdate .."_respData)		 				 		

 }catch err{	

     	 $$$TRACE("Exception in calling MmiAdd/Update: " _err.AsSystemError() _ " _ ErrData: " _ err.Data _ "; ErrCode:" _ err.Code)
    	 set status = $$$ERROR("Exception in calling MmiAdd/Update " _ err.Data)		    	     	 		
    set errText = $SYSTEM.Status.GetOneErrorText(status)
    if ((errText["CONNECTIONERROR")){
	   Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName,errText)
    }Elseif errText["RESEND"{
	   Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName,errText)
    }Elseif errText["DATAERROR"{
	   Set status = ##class(IHC.ITF.ITFCOMMON.Utility).FailMsgError(..%ConfigName,errText)
    }Elseif errText["SHUTDOWN"{
	   Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName,errText)
    }Else{
	    Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName,errText)
    }

  }
 return status
